// GetExcluded checks if the scopes exclude scaling.
func (s Scopes) GetExcluded() (excluded, upscaleOnExclusion bool) { //nolint: nonamedreturns // names clarify the two boolean return values
	return s.isExcluded(), s.GetUpscaleOnExclusion()
}

// GetUpscaleOnExclusion checks if excluded workloads should be upscaled instead of skipped.
func (s Scopes) GetUpscaleOnExclusion() bool {
	for _, scope := range s {
		if scope.UpscaleOnExclusion.isSet {
			return scope.UpscaleOnExclusion.value
		}
	}

	return false
}

// isExcluded checks if the scopes exclude scaling via an exclude timespan or an exclude-until timestamp.
func (s Scopes) isExcluded() bool {
	return s.isExcludedByTimespan() || s.isExcludedByTimestamp()
}

// isExcludedByTimespan checks if the uppermost scope that sets Exclude is currently in an exclude timespan.
func (s Scopes) isExcludedByTimespan() bool {
	for _, scope := range s {
		if scope.Exclude == nil {
			continue
		}

		return scope.Exclude.inTimeSpans()
	}

	return false
}

// isExcludedByTimestamp checks if the uppermost scope that sets ExcludeUntil is still excluded.
func (s Scopes) isExcludedByTimestamp() bool {
	for _, scope := range s {
		if scope.ExcludeUntil == nil {
			continue
		}

		return scope.ExcludeUntil.After(time.Now())
	}

	return false
}

